use std::sync::Arc;use async_trait::async_trait;use crate::{domain::errors::DomainError,ports::{inbound::coude_prime::CoudePrimeUseCase,outbound::coude_prime_repository::CoudePrimeRepository}};pub struct CoudePrimeService{repo:Arc<dyn CoudePrimeRepository>}impl CoudePrimeService{pub fn new(repo:Arc<dyn CoudePrimeRepository>)->Self{Self{repo}}}#[async_trait]impl CoudePrimeUseCase for CoudePrimeService{async fn place(&self,guild_id:&str,target_id:&str,target_name:&str,placer_id:&str,placer_name:&str,amount:i64)->Result<(),DomainError>{if target_id==placer_id{return Err(DomainError::Validation("impossible de poser une prime sur soi".into()))}if amount<=0{return Err(DomainError::Validation("montant invalide".into()))}self.repo.place(guild_id,target_id,target_name,placer_id,placer_name,amount).await}}
